package in.asmj.ride.web;

import in.asmj.ride.model.*;
import in.asmj.ride.repo.*;
import in.asmj.ride.service.RideNotificationService;
import in.asmj.ride.service.AgentVehicleAuthorizationService;
import in.asmj.ride.service.VehicleReservationLockService;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.core.Authentication;
import java.time.*;import java.util.*;

@Controller
public class RentalMarketplaceController {
 private final RentalBookingRepository bookings; private final VehicleRepository vehicles; private final UserAccountRepository users; private final RideNotificationService notifications; private final RentalReviewRepository reviews; private final AgentVehicleAuthorizationRepository authorizations; private final AgentVehicleAuthorizationService authorizationService; private final ServiceCityRepository cities; private final VehicleReservationLockService reservationLocks; private final RentalVoucherRepository vouchers;
 public RentalMarketplaceController(RentalBookingRepository b,VehicleRepository v,UserAccountRepository u,RideNotificationService n,RentalReviewRepository r,AgentVehicleAuthorizationRepository ar,AgentVehicleAuthorizationService as,ServiceCityRepository c,VehicleReservationLockService locks,RentalVoucherRepository vr){bookings=b;vehicles=v;users=u;notifications=n;reviews=r;authorizations=ar;authorizationService=as;cities=c;reservationLocks=locks;vouchers=vr;}
 private UserAccount me(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow();}
 private boolean providerOwns(UserAccount u,Vehicle v){return v.getOwnerId()!=null&&v.getOwnerId().equals(u.getId());}
 private boolean manages(UserAccount u,Vehicle v,String permission){return providerOwns(u,v)||(u.hasGrantedRole("TRAVEL_AGENT")&&authorizationService.canManage(u.getId(),v.getId(),permission));}
 private boolean route(Vehicle v,String from,String to,String journey){String fromCity=from.split("::")[0],toCity=to.split("::")[0];boolean outward=fromCity.equals(toCity)||v.getAllowedRouteKeys().contains(fromCity+">"+toCity);boolean reverse=fromCity.equals(toCity)||v.getAllowedRouteKeys().contains(toCity+">"+fromCity);return v.getPickupLocationKeys().contains(from)&&v.getDropLocationKeys().contains(to)&&outward&&(!"ONE_WAY".equals(journey)||v.isSupportsOneWay())&&(!"ROUND_TRIP".equals(journey)||(v.isSupportsRoundTrip()&&v.getPickupLocationKeys().contains(to)&&v.getDropLocationKeys().contains(from)&&reverse));}
 private boolean overlaps(Vehicle v,LocalDateTime start,LocalDateTime end){return bookings.findByVehicleIdAndStatusIn(v.getId(),List.of("REQUESTED","ACCEPTED","DRIVER_ASSIGNED","DRIVER_DECLINED","DRIVER_ACCEPTED","IN_PROGRESS","COMPLETED_PENDING_PAYMENT")).stream().anyMatch(b->b.getPickupAt()!=null&&b.getReturnAt()!=null&&start.isBefore(b.getReturnAt())&&end.isAfter(b.getPickupAt()));}

 private boolean voucherEligible(RentalVoucher x,Vehicle v,UserAccount customer){Instant now=Instant.now();if(x==null||!"ACTIVE".equals(x.getStatus())||x.getStartsAt()==null||x.getExpiresAt()==null||now.isBefore(x.getStartsAt())||now.isAfter(x.getExpiresAt())||x.getRedeemedCount()>=x.getMaximumUses())return false;if(!x.getVehicleIds().isEmpty()&&!x.getVehicleIds().contains(v.getId()))return false;if(!Objects.equals(x.getProviderId(),v.getOwnerId())&&!Objects.equals(x.getProviderId(),v.getManagingAgentId()))return false;return bookings.findByVoucherIdAndCustomerId(x.getId(),customer.getId()).size()<x.getMaximumUsesPerCustomer();}
 private double discount(RentalVoucher x,double amount){if(amount<x.getMinimumBookingAmount())return 0;double d="PERCENT".equals(x.getDiscountType())?amount*x.getDiscountValue()/100.0:x.getDiscountValue();if(x.getMaximumDiscountAmount()>0)d=Math.min(d,x.getMaximumDiscountAmount());return Math.max(0,Math.min(amount,d));}
 @GetMapping("/rentals/vouchers") public String voucherPage(Authentication a,Model m){UserAccount u=me(a);if(!u.hasGrantedRole("FLEET_OWNER")&&!u.hasGrantedRole("TRAVEL_AGENT"))return "access-denied";m.addAttribute("vouchers",vouchers.findByProviderIdOrderByCreatedAtDesc(u.getId()));m.addAttribute("vehicles",vehicles.findAll().stream().filter(v->manages(u,v,"MANAGE_LISTING")).toList());return "rental-vouchers";}
 @PostMapping("/rentals/vouchers/create") public String createVoucher(Authentication a,@RequestParam String code,@RequestParam String title,@RequestParam String discountType,@RequestParam double discountValue,@RequestParam(defaultValue="0") double minimumBookingAmount,@RequestParam(defaultValue="0") double maximumDiscountAmount,@RequestParam(defaultValue="100") int maximumUses,@RequestParam(defaultValue="1") int maximumUsesPerCustomer,@RequestParam String startsAt,@RequestParam String expiresAt,@RequestParam(required=false) List<String> vehicleIds){UserAccount u=me(a);if(!u.hasGrantedRole("FLEET_OWNER")&&!u.hasGrantedRole("TRAVEL_AGENT"))return "access-denied";String normalized=code.trim().toUpperCase(Locale.ROOT);if(!normalized.matches("[A-Z0-9_-]{4,20}")||vouchers.findByCodeIgnoreCase(normalized).isPresent()||!List.of("PERCENT","FIXED").contains(discountType)||!Double.isFinite(discountValue)||discountValue<=0||("PERCENT".equals(discountType)&&discountValue>100)||minimumBookingAmount<0||maximumDiscountAmount<0||maximumUses<1||maximumUsesPerCustomer<1)return "redirect:/rentals/vouchers?error=validation";List<String> scoped=new ArrayList<>();if(vehicleIds!=null)for(String vid:vehicleIds){Vehicle v=vehicles.findById(vid).orElse(null);if(v==null||!manages(u,v,"MANAGE_LISTING"))return "redirect:/rentals/vouchers?error=vehicle";scoped.add(vid);}Instant start=LocalDateTime.parse(startsAt).atZone(ZoneId.systemDefault()).toInstant(),end=LocalDateTime.parse(expiresAt).atZone(ZoneId.systemDefault()).toInstant();if(!end.isAfter(start))return "redirect:/rentals/vouchers?error=dates";RentalVoucher x=new RentalVoucher();x.setCode(normalized);x.setTitle(title.trim());x.setProviderId(u.getId());x.setProviderRole(u.hasGrantedRole("TRAVEL_AGENT")?"TRAVEL_AGENT":"FLEET_OWNER");x.setDiscountType(discountType);x.setDiscountValue(discountValue);x.setMinimumBookingAmount(minimumBookingAmount);x.setMaximumDiscountAmount(maximumDiscountAmount);x.setMaximumUses(maximumUses);x.setMaximumUsesPerCustomer(maximumUsesPerCustomer);x.setStartsAt(start);x.setExpiresAt(end);x.setVehicleIds(scoped);vouchers.save(x);for(UserAccount c:users.findByRoleIn(List.of("CUSTOMER")))if("APPROVED".equals(c.getStatus()))notifications.notifyUser(c.getId(),"New rental voucher: "+normalized,title+" — "+( "PERCENT".equals(discountType)?discountValue+"% off":"₹"+discountValue+" off")+". Check eligibility and expiry before booking.","/rentals/search",x.getId(),"RENTAL_VOUCHER");return "redirect:/rentals/vouchers?created";}
 @PostMapping("/rentals/vouchers/{id}/disable") public String disableVoucher(Authentication a,@PathVariable String id){UserAccount u=me(a);RentalVoucher x=vouchers.findById(id).orElseThrow();if(!u.getId().equals(x.getProviderId()))return "access-denied";x.setStatus("DISABLED");vouchers.save(x);return "redirect:/rentals/vouchers?disabled";}
 @GetMapping("/rentals/search") public String searchPage(Model m){m.addAttribute("cities",cities.findByActiveTrueOrderByCityAsc());return "rental-search";}
 @PostMapping("/rentals/search") public String search(@RequestParam String pickupKey,@RequestParam String dropKey,@RequestParam String pickupAt,@RequestParam String returnAt,@RequestParam(defaultValue="ONE_WAY") String journey,@RequestParam(defaultValue="WITH_DRIVER") String mode,Model m){LocalDateTime start=LocalDateTime.parse(pickupAt),end=LocalDateTime.parse(returnAt);if(!end.isAfter(start)||start.isBefore(LocalDateTime.now())||!List.of("ONE_WAY","ROUND_TRIP").contains(journey)||!List.of("WITH_DRIVER","SELF_DRIVE").contains(mode))return "redirect:/rentals/search?error=dates";
 List<Vehicle> found=vehicles.findByStatus("APPROVED").stream().filter(v->"ACTIVE".equals(v.getOperationalStatus())&&route(v,pickupKey,dropKey,journey)&&("WITH_DRIVER".equals(mode)?v.isSupportsWithDriver():v.isSupportsSelfDrive())&&!overlaps(v,start,end)).toList();
 m.addAttribute("vehicles",found);m.addAttribute("pickupKey",pickupKey);m.addAttribute("dropKey",dropKey);m.addAttribute("pickupAt",pickupAt);m.addAttribute("returnAt",returnAt);m.addAttribute("journey",journey);m.addAttribute("mode",mode);m.addAttribute("availableVouchers",vouchers.findAll().stream().filter(x->x.getExpiresAt()!=null&&x.getStartsAt()!=null&&Instant.now().compareTo(x.getStartsAt())>=0&&Instant.now().compareTo(x.getExpiresAt())<=0&&"ACTIVE".equals(x.getStatus())&&x.getRedeemedCount()<x.getMaximumUses()).filter(x->found.stream().anyMatch(v->(Objects.equals(x.getProviderId(),v.getOwnerId())||Objects.equals(x.getProviderId(),v.getManagingAgentId()))&&(x.getVehicleIds().isEmpty()||x.getVehicleIds().contains(v.getId())))).toList());return "rental-results";}
 @PostMapping("/rentals/book") public String requestBooking(Authentication a,@RequestParam String vehicleId,@RequestParam String pickupKey,@RequestParam String dropKey,@RequestParam String pickupAt,@RequestParam String returnAt,@RequestParam(defaultValue="ONE_WAY") String journey,@RequestParam(defaultValue="WITH_DRIVER") String mode,@RequestParam(required=false) String note,@RequestParam(required=false) String voucherCode){UserAccount customer=me(a);Vehicle v=vehicles.findById(vehicleId).orElseThrow();LocalDateTime start=LocalDateTime.parse(pickupAt),end=LocalDateTime.parse(returnAt);
 if(!customer.hasGrantedRole("CUSTOMER")||!List.of("ONE_WAY","ROUND_TRIP").contains(journey)||!List.of("WITH_DRIVER","SELF_DRIVE").contains(mode)||!"APPROVED".equals(v.getStatus())||!"ACTIVE".equals(v.getOperationalStatus())||!route(v,pickupKey,dropKey,journey)||("WITH_DRIVER".equals(mode)&&!v.isSupportsWithDriver())||("SELF_DRIVE".equals(mode)&&!v.isSupportsSelfDrive())||!end.isAfter(start)||start.isBefore(LocalDateTime.now()))return "redirect:/rentals/search?error=unavailable";String lock=reservationLocks.tryAcquire(v.getId());if(lock==null)return "redirect:/rentals/search?error=busy";if(overlaps(v,start,end)){reservationLocks.release(v.getId(),lock);return "redirect:/rentals/search?error=busy";}
 RentalBooking b=new RentalBooking();b.setCustomerId(customer.getId());b.setVehicleId(v.getId());b.setVehicleOwnerId(v.getOwnerId());b.setManagingAgentId(v.getManagingAgentId());b.setRentalMode(mode);b.setRentalType(journey);b.setPickupAt(start);b.setReturnAt(end);b.setPickupAddress(pickupKey);b.setDropAddress(dropKey);b.setStatus("REQUESTED");b.setPaymentStatus("PENDING");b.setPaymentNote(note);if(voucherCode!=null&&!voucherCode.isBlank()){RentalVoucher vx=vouchers.findByCodeIgnoreCase(voucherCode.trim()).orElse(null);if(!voucherEligible(vx,v,customer)){reservationLocks.release(v.getId(),lock);return "redirect:/rentals/search?error=voucher";}b.setVoucherId(vx.getId());b.setVoucherCode(vx.getCode());}try{bookings.save(b);}finally{reservationLocks.release(v.getId(),lock);}
 UserAccount owner=users.findById(v.getOwnerId()).orElse(null);if(owner!=null)notifications.notifyUser(owner.getId(),"New rental booking request","A customer requested "+v.getRegistrationNumber()+" for "+start+". Review and quote the booking.","/rentals/provider",b.getId(),"RENTAL_REQUEST");for(AgentVehicleAuthorization auth:authorizations.findByOwnerIdAndStatus(v.getOwnerId(),"APPROVED")){if(auth.getVehicleId().equals(v.getId())&&auth.getPermissions().contains("MANAGE_BOOKINGS"))notifications.notifyUser(auth.getAgentId(),"New partner vehicle booking","A customer requested a vehicle you are authorized to manage.","/rentals/provider",b.getId(),"RENTAL_REQUEST");}return "redirect:/rentals/my-bookings?requested";}
 @GetMapping("/rentals/my-bookings") public String customerBookings(Authentication a,Model m){m.addAttribute("bookings",bookings.findByCustomerIdOrderByCreatedAtDesc(me(a).getId()));return "rental-bookings";}
 @GetMapping("/rentals/provider") public String providerBookings(Authentication a,Model m){UserAccount u=me(a);if(!u.hasGrantedRole("FLEET_OWNER")&&!u.hasGrantedRole("TRAVEL_AGENT"))return "access-denied";List<RentalBooking> rows=new ArrayList<>(bookings.findByVehicleOwnerIdOrManagingAgentIdOrderByCreatedAtDesc(u.getId(),u.getId()));if(u.hasGrantedRole("TRAVEL_AGENT")){for(AgentVehicleAuthorization auth:authorizations.findByAgentIdAndStatus(u.getId(),"APPROVED")){if(auth.getPermissions().contains("MANAGE_BOOKINGS"))for(RentalBooking b:bookings.findByVehicleIdAndStatusIn(auth.getVehicleId(),List.of("REQUESTED","ACCEPTED","DRIVER_ASSIGNED","DRIVER_DECLINED","DRIVER_ACCEPTED","IN_PROGRESS","COMPLETED_PENDING_PAYMENT","PAYMENT_DISPUTED")))if(rows.stream().noneMatch(x->x.getId().equals(b.getId())))rows.add(b);}}m.addAttribute("bookings",rows);m.addAttribute("drivers",users.findAll().stream().filter(x->x.hasGrantedRole("DRIVER")&&"APPROVED".equals(x.getStatus())&&x.isMobileVerified()&&(u.getId().equals(x.getFleetOwnerId())||u.hasGrantedRole("TRAVEL_AGENT"))).toList());return "rental-provider-bookings";}
 @PostMapping("/rentals/{id}/reject") public String reject(Authentication a,@PathVariable String id,@RequestParam(required=false) String reason){UserAccount u=me(a);RentalBooking b=bookings.findById(id).orElseThrow();Vehicle v=vehicles.findById(b.getVehicleId()).orElseThrow();if(!manages(u,v,"MANAGE_BOOKINGS")||!"REQUESTED".equals(b.getStatus()))return "redirect:/rentals/provider?error=reject";b.setStatus("REJECTED");b.setPaymentNote(reason);bookings.save(b);notifications.notifyUser(b.getCustomerId(),"Rental request declined","The provider could not accept this request. Please search for another vehicle.","/rentals/search",b.getId(),"RENTAL_REJECTED");return "redirect:/rentals/provider?rejected";}
 @PostMapping("/rentals/{id}/cancel") public String cancel(Authentication a,@PathVariable String id){UserAccount c=me(a);RentalBooking b=bookings.findById(id).orElseThrow();if(!c.getId().equals(b.getCustomerId())||!"REQUESTED".equals(b.getStatus()))return "redirect:/rentals/my-bookings?error=cancel";b.setStatus("CANCELLED");bookings.save(b);notifications.notifyUser(b.getVehicleOwnerId(),"Rental request cancelled","Customer cancelled a pending rental request.","/rentals/provider",b.getId(),"RENTAL_CANCELLED");return "redirect:/rentals/my-bookings?cancelled";}
 @PostMapping("/rentals/{id}/accept") public String accept(Authentication a,@PathVariable String id,@RequestParam double quotedAmount,@RequestParam(required=false) String driverId,@RequestParam(required=false) String paymentInstructions,@RequestParam(defaultValue="NONE") String providerDiscountType,@RequestParam(defaultValue="0") double providerDiscountValue){
  UserAccount u=me(a);RentalBooking b=bookings.findById(id).orElseThrow();Vehicle v=vehicles.findById(b.getVehicleId()).orElseThrow();
  if(!manages(u,v,"MANAGE_BOOKINGS")||!"REQUESTED".equals(b.getStatus())||!Double.isFinite(quotedAmount)||quotedAmount<=0)return "redirect:/rentals/provider?error=accept";
  String lock=reservationLocks.tryAcquire(v.getId());if(lock==null)return "redirect:/rentals/provider?error=busy";
  double payable=quotedAmount;
  try{
   if(overlapsExcept(v,b))return "redirect:/rentals/provider?error=overlap";
   if("WITH_DRIVER".equals(b.getRentalMode())){
    if(!providerOwns(u,v)&&!authorizationService.canManage(u.getId(),v.getId(),"ASSIGN_DRIVER"))return "redirect:/rentals/provider?error=permission";
    UserAccount d=users.findById(driverId==null?"":driverId).orElse(null);
    if(d==null||!d.hasGrantedRole("DRIVER")||!"APPROVED".equals(d.getStatus())||!d.isMobileVerified()||!d.isAvailable()||(!u.getId().equals(d.getFleetOwnerId())&&!u.getId().equals(v.getOwnerId())))return "redirect:/rentals/provider?error=driver";
    b.setAssignedDriverId(d.getId());b.setAssignedDriverName(d.getName());b.setStatus("DRIVER_ASSIGNED");
    b.setAssignedVehicleId(v.getId());b.setAssignedVehicleNumber(v.getRegistrationNumber());
    notifications.notifyUser(d.getId(),"Rental assignment","A rental booking has been assigned to you. Please accept or decline.","/rentals/driver",b.getId(),"RENTAL_DRIVER_ASSIGNMENT");
   } else {b.setAssignedVehicleId(v.getId());b.setAssignedVehicleNumber(v.getRegistrationNumber());b.setStatus("ACCEPTED");}
   b.setOriginalQuotedAmount(quotedAmount);payable=quotedAmount;if(!List.of("NONE","PERCENT","FIXED").contains(providerDiscountType)||!Double.isFinite(providerDiscountValue)||providerDiscountValue<0||("PERCENT".equals(providerDiscountType)&&providerDiscountValue>100))return "redirect:/rentals/provider?error=discount";double providerOff="PERCENT".equals(providerDiscountType)?quotedAmount*providerDiscountValue/100.0:("FIXED".equals(providerDiscountType)?providerDiscountValue:0);providerOff=Math.min(quotedAmount,Math.max(0,providerOff));b.setProviderDiscountAmount(providerOff);payable-=providerOff;if(b.getVoucherId()!=null){RentalVoucher vx=vouchers.findById(b.getVoucherId()).orElse(null);if(vx==null||!"ACTIVE".equals(vx.getStatus())||vx.getExpiresAt()==null||Instant.now().isAfter(vx.getExpiresAt())||vx.getRedeemedCount()>=vx.getMaximumUses()||(!vx.getVehicleIds().isEmpty()&&!vx.getVehicleIds().contains(v.getId()))||(!Objects.equals(vx.getProviderId(),v.getOwnerId())&&!Objects.equals(vx.getProviderId(),v.getManagingAgentId())))return "redirect:/rentals/provider?error=voucher";double off=discount(vx,payable);if(off<=0)return "redirect:/rentals/provider?error=voucher";b.setDiscountAmount(off);payable-=off;vx.setRedeemedCount(vx.getRedeemedCount()+1);vouchers.save(vx);}b.setDiscountAmount(b.getDiscountAmount()+providerOff);b.setQuotedAmount(payable);String paymentInfo=paymentInstructions==null||paymentInstructions.isBlank()?v.getPaymentInstructions():paymentInstructions.trim();b.setProviderPaymentInstructions(paymentInfo==null?null:paymentInfo.substring(0,Math.min(1000,paymentInfo.length())));b.setBookingAcceptedById(u.getId());b.setBookingAcceptedByRole(u.hasGrantedRole("TRAVEL_AGENT")?"TRAVEL_AGENT":"VEHICLE_OWNER");bookings.save(b);
  } finally {reservationLocks.release(v.getId(),lock);}
  notifications.notifyUser(b.getCustomerId(),"Rental request accepted","Your rental request was accepted. Original fare: ₹"+quotedAmount+", discount: ₹"+b.getDiscountAmount()+", payable: ₹"+payable,"/rentals/my-bookings",b.getId(),"RENTAL_ACCEPTED");return "redirect:/rentals/provider?accepted";
 }
 private boolean overlapsExcept(Vehicle v,RentalBooking current){return bookings.findByVehicleIdAndStatusIn(v.getId(),List.of("REQUESTED","ACCEPTED","DRIVER_ASSIGNED","DRIVER_DECLINED","DRIVER_ACCEPTED","IN_PROGRESS","COMPLETED_PENDING_PAYMENT")).stream().anyMatch(x->!x.getId().equals(current.getId())&&x.getPickupAt().isBefore(current.getReturnAt())&&x.getReturnAt().isAfter(current.getPickupAt()));}
 @PostMapping("/rentals/{id}/driver/reassign") public String reassignDriver(Authentication a,@PathVariable String id,@RequestParam String driverId){UserAccount u=me(a);RentalBooking b=bookings.findById(id).orElseThrow();Vehicle v=vehicles.findById(b.getVehicleId()).orElseThrow();if(!manages(u,v,"MANAGE_BOOKINGS")||(!providerOwns(u,v)&&!authorizationService.canManage(u.getId(),v.getId(),"ASSIGN_DRIVER"))||!"DRIVER_DECLINED".equals(b.getStatus()))return "redirect:/rentals/provider?error=permission";UserAccount d=users.findById(driverId).orElse(null);if(d==null||!d.hasGrantedRole("DRIVER")||!"APPROVED".equals(d.getStatus())||!d.isMobileVerified()||!d.isAvailable()||(!u.getId().equals(d.getFleetOwnerId())&&!u.getId().equals(v.getOwnerId())))return "redirect:/rentals/provider?error=driver";b.setAssignedDriverId(d.getId());b.setAssignedDriverName(d.getName());b.setStatus("DRIVER_ASSIGNED");bookings.save(b);notifications.notifyUser(d.getId(),"New rental assignment","A rental booking has been reassigned to you. Please respond.","/rentals/driver",b.getId(),"RENTAL_DRIVER_ASSIGNMENT");return "redirect:/rentals/provider?reassigned";}
 @PostMapping("/rentals/{id}/driver/respond") public String driverRespond(Authentication a,@PathVariable String id,@RequestParam String response){UserAccount d=me(a);RentalBooking b=bookings.findById(id).orElseThrow();if(!d.getId().equals(b.getAssignedDriverId())||!"DRIVER_ASSIGNED".equals(b.getStatus())||!List.of("ACCEPT","DECLINE").contains(response))return "redirect:/rentals/driver?error=denied";if("ACCEPT".equals(response)){b.setStatus("DRIVER_ACCEPTED");notifications.notifyUser(b.getCustomerId(),"Driver accepted","Your assigned driver accepted the rental.","/rentals/my-bookings",b.getId(),"RENTAL_DRIVER_ACCEPTED");if(b.getBookingAcceptedById()!=null)notifications.notifyUser(b.getBookingAcceptedById(),"Driver accepted assignment","The assigned driver accepted the rental.","/rentals/provider",b.getId(),"RENTAL_DRIVER_ACCEPTED");}else{b.setStatus("DRIVER_DECLINED");notifications.notifyUser(b.getVehicleOwnerId(),"Driver declined","Please assign another driver or contact the customer.","/rentals/provider",b.getId(),"RENTAL_DRIVER_DECLINED");if(b.getBookingAcceptedById()!=null&&!b.getBookingAcceptedById().equals(b.getVehicleOwnerId()))notifications.notifyUser(b.getBookingAcceptedById(),"Driver declined","Please assign another driver or contact the customer.","/rentals/provider",b.getId(),"RENTAL_DRIVER_DECLINED");}bookings.save(b);return "redirect:/rentals/driver";}
 @GetMapping("/rentals/driver") public String driverBookings(Authentication a,Model m){m.addAttribute("bookings",bookings.findByAssignedDriverIdOrderByCreatedAtDesc(me(a).getId()));return "rental-driver";}
 @PostMapping("/rentals/{id}/journey/start") public String startJourney(Authentication a,@PathVariable String id,@RequestParam double startKm){UserAccount d=me(a);RentalBooking b=bookings.findById(id).orElseThrow();if(!d.getId().equals(b.getAssignedDriverId())||!"DRIVER_ACCEPTED".equals(b.getStatus())||(b.getPickupAt()!=null&&LocalDateTime.now().isBefore(b.getPickupAt()))||!Double.isFinite(startKm)||startKm<0)return "redirect:/rentals/driver?error=start";b.setStartKm(startKm);b.setJourneyStartedAt(Instant.now());b.setStatus("IN_PROGRESS");bookings.save(b);return "redirect:/rentals/driver?started";}
 @PostMapping("/rentals/{id}/journey/complete") public String completeJourney(Authentication a,@PathVariable String id,@RequestParam double endKm){UserAccount d=me(a);RentalBooking b=bookings.findById(id).orElseThrow();if(!d.getId().equals(b.getAssignedDriverId())||!"IN_PROGRESS".equals(b.getStatus())||b.getStartKm()==null||!Double.isFinite(endKm)||endKm<=b.getStartKm()||endKm-b.getStartKm()>5000)return "redirect:/rentals/driver?error=odometer";b.setEndKm(endKm);b.setJourneyCompletedAt(Instant.now());b.setFinalAmount(b.getQuotedAmount());b.setInvoiceNumber("ASMJ-RNT-"+b.getId().substring(Math.max(0,b.getId().length()-8)).toUpperCase(Locale.ROOT));b.setInvoiceStatus("ISSUED");b.setStatus("COMPLETED_PENDING_PAYMENT");bookings.save(b);notifications.notifyUser(b.getCustomerId(),"Rental invoice ready","Your journey is complete. Invoice "+b.getInvoiceNumber()+" amount ₹"+b.getFinalAmount()+" is ready.","/rentals/my-bookings",b.getId(),"RENTAL_INVOICE");notifications.notifyUser(b.getVehicleOwnerId(),"Rental completed","Journey completed; customer invoice issued.","/rentals/provider",b.getId(),"RENTAL_COMPLETED");return "redirect:/rentals/driver?completed";}
 @PostMapping("/rentals/{id}/self-drive/complete") public String completeSelfDrive(Authentication a,@PathVariable String id,@RequestParam double startKm,@RequestParam double endKm,@RequestParam double finalAmount){UserAccount u=me(a);RentalBooking b=bookings.findById(id).orElseThrow();Vehicle v=vehicles.findById(b.getVehicleId()).orElseThrow();if(!manages(u,v,"MANAGE_BOOKINGS")||!"ACCEPTED".equals(b.getStatus())||!"SELF_DRIVE".equals(b.getRentalMode())||(b.getReturnAt()!=null&&LocalDateTime.now().isBefore(b.getReturnAt()))||!Double.isFinite(startKm)||!Double.isFinite(endKm)||endKm<=startKm||endKm-startKm>5000||!Double.isFinite(finalAmount)||finalAmount<=0)return "redirect:/rentals/provider?error=selfDrive";b.setStartKm(startKm);b.setEndKm(endKm);b.setJourneyStartedAt(Instant.now());b.setJourneyCompletedAt(Instant.now());b.setFinalAmount(finalAmount);b.setInvoiceNumber("ASMJ-RNT-"+b.getId().substring(Math.max(0,b.getId().length()-8)).toUpperCase(Locale.ROOT));b.setInvoiceStatus("ISSUED");b.setStatus("COMPLETED_PENDING_PAYMENT");bookings.save(b);notifications.notifyUser(b.getCustomerId(),"Rental invoice ready","Your self-drive rental is complete. Invoice "+b.getInvoiceNumber()+" amount ₹"+finalAmount+" is ready.","/rentals/my-bookings",b.getId(),"RENTAL_INVOICE");return "redirect:/rentals/provider?invoiceIssued";}
 @PostMapping("/rentals/{id}/payment/report") public String reportPayment(Authentication a,@PathVariable String id,@RequestParam String method,@RequestParam(required=false) String reference,@RequestParam(required=false) String note){UserAccount c=me(a);RentalBooking b=bookings.findById(id).orElseThrow();if(!c.getId().equals(b.getCustomerId())||!"COMPLETED_PENDING_PAYMENT".equals(b.getStatus())||!List.of("UPI","CASH","BANK_TRANSFER").contains(method))return "redirect:/rentals/my-bookings?error=payment";if(("UPI".equals(method)||"BANK_TRANSFER".equals(method))&&(reference==null||reference.isBlank()))return "redirect:/rentals/my-bookings?error=reference";b.setPaymentMethod(method);b.setPaymentReference(reference);b.setPaymentNote(note);b.setPaymentReportedAt(Instant.now());b.setPaymentStatus("REPORTED");bookings.save(b);notifications.notifyUser(b.getVehicleOwnerId(),"Rental payment reported","Customer reports payment by "+method+". Verify receipt before marking paid.","/rentals/provider",b.getId(),"RENTAL_PAYMENT_REPORTED");if(b.getBookingAcceptedById()!=null&&!b.getBookingAcceptedById().equals(b.getVehicleOwnerId()))notifications.notifyUser(b.getBookingAcceptedById(),"Rental payment reported","Customer reports payment. Verify receipt before marking paid.","/rentals/provider",b.getId(),"RENTAL_PAYMENT_REPORTED");return "redirect:/rentals/my-bookings?reported";}
 @PostMapping("/rentals/{id}/payment/verify") public String verifyPayment(Authentication a,@PathVariable String id,@RequestParam String decision,@RequestParam(required=false) String reason){UserAccount u=me(a);RentalBooking b=bookings.findById(id).orElseThrow();Vehicle v=vehicles.findById(b.getVehicleId()).orElseThrow();if(!manages(u,v,"MANAGE_BOOKINGS")||!"REPORTED".equals(b.getPaymentStatus()))return "redirect:/rentals/provider?error=payment";if("VERIFY".equals(decision)){b.setPaymentStatus("VERIFIED");b.setPaymentVerifiedAt(Instant.now());b.setPaymentVerifiedById(u.getId());b.setStatus("COMPLETED");}else if("DISPUTE".equals(decision)){b.setPaymentStatus("DISPUTED");b.setPaymentDisputeReason(reason);}else return "redirect:/rentals/provider?error=decision";bookings.save(b);notifications.notifyUser(b.getCustomerId(),"Rental payment update","Payment status: "+b.getPaymentStatus(),"/rentals/my-bookings",b.getId(),"RENTAL_PAYMENT_UPDATE");return "redirect:/rentals/provider?paymentUpdated";}
 @PostMapping("/rentals/{id}/review") public String review(Authentication a,@PathVariable String id,@RequestParam int vehicleRating,@RequestParam int providerRating,@RequestParam(required=false,defaultValue="0") int driverRating,@RequestParam(required=false) String comment){UserAccount c=me(a);RentalBooking b=bookings.findById(id).orElseThrow();if(!c.getId().equals(b.getCustomerId())||!"COMPLETED".equals(b.getStatus())||reviews.findByBookingId(id).isPresent()||vehicleRating<1||vehicleRating>5||providerRating<1||providerRating>5||("WITH_DRIVER".equals(b.getRentalMode())&&(driverRating<1||driverRating>5)))return "redirect:/rentals/my-bookings?error=review";RentalReview r=new RentalReview();r.setBookingId(id);r.setCustomerId(c.getId());r.setVehicleId(b.getVehicleId());r.setOwnerId(b.getVehicleOwnerId());r.setAgentId("TRAVEL_AGENT".equals(b.getBookingAcceptedByRole())?b.getBookingAcceptedById():b.getManagingAgentId());r.setDriverId(b.getAssignedDriverId());r.setVehicleRating(vehicleRating);r.setProviderRating(providerRating);r.setDriverRating(driverRating);r.setComment(comment);reviews.save(r);b.setReviewStatus("SUBMITTED");bookings.save(b);return "redirect:/rentals/my-bookings?reviewed";}
}
